/**
 * STEP 17.80 — compile-time Prisma runtime compatibility probe.
 *
 * This file is intentionally type-only: it must not add either runtime client
 * to an application bundle. The Node and Cloudflare clients are generated by
 * the two generators in each schema. A failed assertion means the clients do
 * not share the claimed public TypeScript surface; do not paper over it with
 * casts or a union.
 */
import type { PrismaClient as MainNodeClient } from "@prisma/client";
import type { PrismaClient as MainWorkerClient } from "@/lib/generated/client/client";
import type { PrismaClient as StoreNodeClient } from "@/lib/generated/store-node-client";
import type { PrismaClient as StoreWorkerClient } from "@/lib/generated/store-client/client";

type IsAssignable<From, To> = [From] extends [To] ? true : false;
type AssertTrue<Value extends true> = Value;

export type MainWorkerToNodeCompatibility = AssertTrue<
  IsAssignable<MainWorkerClient, MainNodeClient>
>;
export type MainNodeToWorkerCompatibility = AssertTrue<
  IsAssignable<MainNodeClient, MainWorkerClient>
>;
export type StoreWorkerToNodeCompatibility = AssertTrue<
  IsAssignable<StoreWorkerClient, StoreNodeClient>
>;
export type StoreNodeToWorkerCompatibility = AssertTrue<
  IsAssignable<StoreNodeClient, StoreWorkerClient>
>;
